<?php declare(strict_types=1); ?>
<div class="cs-library-toolbar"><div><span class="jt-kicker">Explora el trabajo</span><h2>Casos de estudio<span class="cs-total"><?= count($cases) ?></span></h2></div><div class="mi-search"><label class="visually-hidden" for="case-search">Buscar en el portafolio</label><input id="case-search" type="search" placeholder="Buscar un caso…" autocomplete="off" data-case-search><p data-case-count aria-live="polite"><?= count($cases) ?> casos</p></div></div>
<div class="mi-filters" role="group" aria-label="Filtrar casos de estudio"><button type="button" data-case-filter="all" aria-pressed="true">Todos</button><?php foreach ($areas as $area=>$label): ?><button type="button" data-case-filter="<?= e($area) ?>" aria-pressed="false"><?= e($label) ?><span><?= count(array_filter($cases, static fn(array $item): bool => $item['area'] === $area)) ?></span></button><?php endforeach; ?></div>
<div class="mi-case-grid"><?php foreach($cases as $index=>$case): ?>
<article class="mi-case-card<?= professional_case_deliverables($case['id']) ? ' cs-card-original' : '' ?>" data-case-kind="<?= e($case['area']) ?>" data-area="<?= e($case['area']) ?>">
<a href="<?= e(professional_case_url($case)) ?>" class="mi-case-visual" aria-label="Ver caso: <?= e($case['title']) ?>"><?php professional_case_art($case); ?><span class="mi-visual-sector"><?= e($case['sector']) ?></span><span class="cs-image-caption"><?= e($case['discipline']) ?></span></a>
<div class="mi-case-copy"><div class="cs-card-meta"><span class="mi-area-label"><?= e($areas[$case['area']]) ?></span><span class="mi-case-type"><?= e($case['evidence_kind']) ?></span></div><h3><a href="<?= e(professional_case_url($case)) ?>"><?= e($case['title']) ?></a></h3><p><?= e($case['summary']) ?></p><div class="cs-card-result"><strong><?= e($case['headline']) ?></strong><span><?= e($case['headline_label']) ?></span></div><a class="mi-read-case" href="<?= e(professional_case_url($case)) ?>"><span>Explorar el caso</span><span class="cs-link-mark" aria-hidden="true">+</span></a></div>
</article><?php endforeach; ?></div><div class="mi-empty" data-case-empty hidden><h3>No encontramos ese caso.</h3><p>Prueba otro término o vuelve a mostrar todos los proyectos.</p><button class="jt-btn jt-btn-secondary" type="button" data-case-reset>Restablecer filtros</button></div>
